{  
  "sections": [  
    {  
      "role": "hook",  
      "purpose": "جذب توجه با یک تجربه رایج و آشنا: حسرت پس از تکرار یک رفتار ناخوشایند، مثلاً قول دادن به خود برای بیدار شدن زود و دوباره ندادن به آن.",  
      "target_minutes": 3  
    },  
    {  
      "role": "context",  
      "purpose": "معرفی ایدهٔ مرزبندی بین شناخت (فهم از رفتار) و پذیرش (قبول عمقانی آن): بسیاری می‌دانیم چه می‌کنیم، اما هنوز تغییر نمی‌کنیم، چون قلب ما با آن هم‌صدایی ندارد.",  
      "target_minutes": 5  
    },  
    {  
      "role": "turn",  
      "purpose": "نمایش شکاف بین دانستن و پذیرش با مثالی داستانی: شخصی که می‌داند از تنها بودن می‌ترسد، اما تا زمانی که درد آن را در قلب نپذیرد، به روابط ناسالم ادامه می‌دهد.",  
      "target_minutes": 6  
    },  
    {  
      "role": "deepening",  
      "purpose": "بررسی چرایی این شکاف: چگونه شناخت سطحی، دفاعی می‌شود و چرا پذیرش — که شامل آسیب‌پذیری، ایمان و ارتباط با احساسات است — نقطهٔ عبور اصلی است.",  
      "target_minutes": 8  
    },  
    {  
      "role": "resolution",  
      "purpose": "پیشنهاد مسیری عملی: از شناخت به پذیرش — با تمرین شنیدن درونی، پرسش از خود «آیا واقعاً این را می‌پذیرم؟» و پذیرفتن درد به جای فرار از آن.",  
      "target_minutes": 4  
    },  
    {  
      "role": "closing",  
      "purpose": "جمع‌بندی شاعرانه: تغییر نه در سر، که در قلب رخ می‌دهد؛ و شکاف بین دانستن و پذیرش، همان جایی است که نور وارد می‌شود.",  
      "target_minutes": 1  
    }  
  ]  
}
